          {
            "language": "Python",
            "code": "import math\nfrom qiskit import QuantumCircuit\nfrom qiskit.primitives import StatevectorSampler\n\n# Build a Bell state circuit\nqc = QuantumCircuit(2)\nqc.h(0)\nqc.cx(0, 1)\nqc.measure_all()\n\n# Run with a specific number of shots\nshots = 1024\nsampler = StatevectorSampler()\njob = sampler.run([qc], shots=shots)\nresult = job.result()\n\n# Extract counts\npub_result = result[0]\ncounts = pub_result.data.meas.get_counts()\nprint(\"Raw Counts:\", counts)\n\n# Analyze results\nprint(\"\\nStatistical Analysis:\")\nfor outcome, count in counts.items():\n    prob = count / shots\n    # Standard error of a binomial distribution: sqrt(p*(1-p)/N)\n    std_error = math.sqrt((prob * (1 - prob)) / shots)\n    print(f\"State |{outcome}>: Count = {count}, Prob = {prob:.4f} +/- {std_error:.4f}\")"
          }
