            "code": "from qiskit import QuantumCircuit\n\n# Build a representative circuit with various elements\nqc = QuantumCircuit(3, 2)\nqc.h(0)\nqc.cx(0, 1)\nqc.ry(0.5, 2) # Parameterized rotation on qubit 2\nqc.barrier()\nqc.ccx(0, 1, 2) # Toffoli (CCNOT) gate\nqc.measure([0, 1], [0, 1])\n\n# 1. Text-based drawing (prints directly to console)\nprint(\"--- Text Drawing ---\")\nprint(qc.draw(output='text'))\n\n# 2. Matplotlib-based drawing (returns a Figure object)\n# Note: In a Jupyter notebook, simply calling qc.draw('mpl') displays the image.\ntry:\n    fig = qc.draw(output='mpl', style='iqp') # 'iqp' is a professional dark-themed style\n    fig.savefig(\"circuit_mpl.png\", bbox_inches='tight')\n    print(\"\\nMatplotlib drawing saved as 'circuit_mpl.png'\")\nexcept Exception as e:\n    print(\"\\nMatplotlib drawing failed. Ensure matplotlib is installed.\")\n\n# 3. LaTeX-based drawing (returns a Figure object if latex is installed)\ntry:\n    latex_fig = qc.draw(output='latex')\n    latex_fig.savefig(\"circuit_latex.pdf\")\n    print(\"LaTeX drawing saved as 'circuit_latex.pdf'\")\nexcept Exception as e:\n    print(\"LaTeX drawing skipped (requires local LaTeX installation).\")"
